#!/bin/bash
# Proxmox Host Monitor installer, generated by Home Assistant.
#
#   --check   only list existing installations and similar services, change nothing
#   --yes     also remove/disable predecessors without asking (updating an
#             existing Proxmox Host Monitor never asks; other services are
#             never disabled)
set -euo pipefail

VERSION="@VERSION@"
WEBHOOK_URL=@WEBHOOK_URL@

MODE=install
case "${1:-}" in
    --check) MODE=check ;;
    --yes) MODE=yes ;;
    "") ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
esac

if [ "$(id -u)" != 0 ]; then
    echo "Please run as root." >&2
    exit 1
fi

OWN_UNITS="proxmox-host-monitor-reboot proxmox-host-monitor-disks proxmox-host-monitor-guests"
LEGACY_FILES="/etc/systemd/system/proxmox-reboot-status.timer /etc/systemd/system/proxmox-reboot-status.service /usr/local/sbin/report-reboot-status-to-ha"

SBIN=/usr/local/sbin
CONF_DIR=/etc/proxmox-host-monitor
SYSTEMD_DIR=/etc/systemd/system
SMARTD_HOOKS=/etc/smartmontools/run.d
CRON_FILES="/etc/cron.d/* /var/spool/cron/crontabs/root"

# Print "kind<TAB>description<TAB>path" for everything that already exists.
# kind: own (updated), legacy (removed), foreign (smartd hook made
# non-executable), info (only listed, left unchanged).
# Only files of Proxmox Host Monitor and its predecessor are ever replaced.
# Other services are never disabled: a service that posts to a Home Assistant
# webhook or calls smartctl may do something entirely different (backups,
# image updates, ...). A smartd hook that posts to Home Assistant is only
# disabled on the first installation; on updates it was either disabled before
# or re-enabled on purpose.
detect() {
    local own=""
    if [ -e "$SBIN/proxmox-host-monitor-reboot" ]; then
        own=1
        local installed
        installed=$(cat "$CONF_DIR/version" 2>/dev/null || echo unknown)
        printf 'own\tProxmox Host Monitor %s (update to %s)\t%s/proxmox-host-monitor-*\n' \
            "$installed" "$VERSION" "$SBIN"
    fi
    local file
    for file in $LEGACY_FILES; do
        [ -e "$file" ] && printf 'legacy\tProxmox Reboot Update\t%s\n' "$file"
    done

    local unit exec_path
    for unit in "$SYSTEMD_DIR"/*.service; do
        [ -e "$unit" ] || continue
        case "$(basename "$unit" .service)" in
            proxmox-host-monitor-*|proxmox-reboot-status) continue ;;
        esac
        exec_path=$(sed -n 's/^ExecStart=[-@+!]*\([^ ]*\).*/\1/p' "$unit" | head -n 1)
        if grep -qsIE '/api/webhook/|smartctl' "$unit" ${exec_path:+"$exec_path"}; then
            printf 'info\tService reporting to Home Assistant or reading SMART (left unchanged): %s\t%s\n' \
                "$(basename "$unit")" "${exec_path:-$unit}"
        fi
    done

    local hook
    for hook in "$SMARTD_HOOKS"/*; do
        [ -f "$hook" ] && [ -x "$hook" ] || continue
        case "$(basename "$hook")" in
            60proxmox-host-monitor|10mail) continue ;;
        esac
        if [ -z "$own" ] && grep -qsI '/api/webhook/' "$hook"; then
            printf 'foreign\tsmartd hook reporting to Home Assistant\t%s\n' "$hook"
        else
            printf 'info\tsmartd hook (left unchanged)\t%s\n' "$hook"
        fi
    done

    local cron
    for cron in $CRON_FILES; do
        [ -e "$cron" ] || continue
        if grep -qs '/api/webhook/' "$cron"; then
            printf 'info\tCron job reporting to Home Assistant (left unchanged)\t%s\n' "$cron"
        fi
    done
    return 0
}

# Remove the predecessor and disable competing smartd hooks found by detect().
# Everything else is left alone.
replace_found() {
    local kind description path
    while IFS=$'\t' read -r kind description path; do
        case "$kind" in
            legacy)
                case "$path" in
                    *.timer|*.service) systemctl disable --now "$(basename "$path")" 2>/dev/null || true ;;
                esac
                rm -f "$path"
                echo "Removed $path"
                ;;
            foreign)
                if [ "$(dirname "$path")" = "$SMARTD_HOOKS" ] && [ -f "$path" ]; then
                    chmod -x "$path"
                    echo "Disabled smartd hook $path (file kept)"
                fi
                ;;
        esac
    done
}

# Updating the own scripts needs no confirmation; removing or disabling
# anything else does. Matched in bash itself: a pipe into grep -q can fail the
# writer under pipefail and a here-string needs a temp file, and either failure
# would skip the question.
needs_confirmation() {
    local lines=$'\n'"$1" nl=$'\n' tab=$'\t'
    [[ "$lines" == *"${nl}legacy${tab}"* || "$lines" == *"${nl}foreign${tab}"* ]]
}

FOUND=$(detect)

if [ "$MODE" = check ]; then
    [ -n "$FOUND" ] && printf '%s\n' "$FOUND"
    exit 0
fi

if [ -n "$FOUND" ]; then
    echo "Found existing installations or similar services:"
    printf '%s\n' "$FOUND" | while IFS=$'\t' read -r kind description path; do
        case "$kind" in
            own) action="update" ;;
            legacy) action="remove" ;;
            foreign) action="disable" ;;
            *) action="keep" ;;
        esac
        printf '  [%s] %s\n        %s\n' "$action" "$description" "$path"
    done
fi

if [ "$MODE" != yes ] && needs_confirmation "$FOUND"; then
    if ! { exec 3</dev/tty; } 2>/dev/null; then
        echo "No terminal to ask. Re-run with --yes to remove/disable the entries above." >&2
        exit 3
    fi
    read -r -u 3 -p "Remove/disable the entries above and install? [y/N] " answer
    case "$answer" in
        y|Y|yes|j|J|ja) ;;
        *) echo "Aborted, nothing changed."; exit 3 ;;
    esac
fi

command -v pveversion >/dev/null || echo "Warning: this does not look like a Proxmox VE host." >&2

if ! command -v smartctl >/dev/null; then
    DEBIAN_FRONTEND=noninteractive apt-get install -y smartmontools
fi

[ -n "$FOUND" ] && printf '%s\n' "$FOUND" | replace_found

mkdir -p /etc/proxmox-host-monitor
printf '%s\n' "$WEBHOOK_URL" > /etc/proxmox-host-monitor/webhook-url
printf '%s\n' "$VERSION" > /etc/proxmox-host-monitor/version
chmod 600 /etc/proxmox-host-monitor/webhook-url

cat > /usr/local/sbin/proxmox-host-monitor-reboot <<'PHM_EOF'
@REBOOT_SCRIPT@PHM_EOF
cat > /usr/local/sbin/proxmox-host-monitor-disks <<'PHM_EOF'
@DISK_SCRIPT@PHM_EOF
cat > /usr/local/sbin/proxmox-host-monitor-guests <<'PHM_EOF'
@GUEST_SCRIPT@PHM_EOF
chmod 750 /usr/local/sbin/proxmox-host-monitor-reboot /usr/local/sbin/proxmox-host-monitor-disks \
    /usr/local/sbin/proxmox-host-monitor-guests

cat > /etc/systemd/system/proxmox-host-monitor-reboot.service <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report reboot status to Home Assistant
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/proxmox-host-monitor-reboot
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-reboot.timer <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report reboot status every 5 minutes

[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
Persistent=true

[Install]
WantedBy=timers.target
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-disks.service <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report disk health to Home Assistant
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/proxmox-host-monitor-disks
Nice=10
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-disks.timer <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report disk health every 15 minutes

[Timer]
OnBootSec=3min
OnUnitActiveSec=15min
Persistent=true

[Install]
WantedBy=timers.target
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-guests.service <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report container updates to Home Assistant
After=network-online.target pve-guests.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/proxmox-host-monitor-guests
Nice=10
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-guests.timer <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report container updates every 6 hours

[Timer]
OnBootSec=10min
OnUnitActiveSec=6h
Persistent=true

[Install]
WantedBy=timers.target
PHM_EOF

mkdir -p /etc/smartmontools/run.d
cat > /etc/smartmontools/run.d/60proxmox-host-monitor <<'PHM_EOF'
#!/bin/sh
# Report smartd warnings to Home Assistant immediately.
systemctl start --no-block proxmox-host-monitor-disks.service
PHM_EOF
chmod 755 /etc/smartmontools/run.d/60proxmox-host-monitor

systemctl daemon-reload
for unit in $OWN_UNITS; do
    systemctl enable --now "$unit.timer"
done
# Until the setup in Home Assistant is finished, the webhook may still reject
# reports, so a failed first report is retried shortly after instead of failing.
for unit in $OWN_UNITS; do
    if ! systemctl start "$unit.service"; then
        echo "Warning: the first report of $unit failed. The timer retries automatically." >&2
        systemd-run --quiet --on-active=2min --unit="$unit-retry" \
            systemctl start "$unit.service" 2>/dev/null || true
    fi
done
echo "Proxmox Host Monitor $VERSION installed."
